     1→// ============================================================
     2→// minicc.fl - FreeLang Mini Compiler (Self-Hosting Proof)
     3→// ============================================================
     4→//
     5→// Structure:
     6→// 1. Lexer (1000 lines) - Input string → Token array
     7→// 2. Parser (1500 lines) - Token array → AST
     8→// 3. Codegen (400 lines) - AST → C code
     9→// 4. Main (100 lines) - Pipeline
    10→//
    11→// Total: ~3000 lines
    12→// ============================================================
    13→
    14→// ============================================================
    15→// Part 1: LEXER (Tokenization)
    16→// ============================================================
    17→
    18→// Token types
    19→var TOK_EOF: i64 = 0;
    20→var TOK_INT: i64 = 1;
    21→var TOK_IDENT: i64 = 2;
    22→var TOK_PLUS: i64 = 3;
    23→var TOK_MINUS: i64 = 4;
    24→var TOK_STAR: i64 = 5;
    25→var TOK_SLASH: i64 = 6;
    26→var TOK_EQ: i64 = 7;
    27→var TOK_NE: i64 = 8;
    28→var TOK_LT: i64 = 9;
    29→var TOK_GT: i64 = 10;
    30→var TOK_LE: i64 = 11;
    31→var TOK_GE: i64 = 12;
    32→var TOK_ASSIGN: i64 = 13;
    33→var TOK_LPAREN: i64 = 14;
    34→var TOK_RPAREN: i64 = 15;
    35→var TOK_LBRACE: i64 = 16;
    36→var TOK_RBRACE: i64 = 17;
    37→var TOK_SEMICOLON: i64 = 18;
    38→var TOK_COMMA: i64 = 19;
    39→var TOK_COLON: i64 = 20;
    40→var TOK_AND: i64 = 21;
    41→var TOK_OR: i64 = 22;
    42→var TOK_NOT: i64 = 23;
    43→var TOK_FN: i64 = 24;
    44→var TOK_LET: i64 = 25;
    45→var TOK_VAR: i64 = 26;
    46→var TOK_RETURN: i64 = 27;
    47→var TOK_IF: i64 = 28;
    48→var TOK_ELSE: i64 = 29;
    49→var TOK_WHILE: i64 = 30;
    50→var TOK_FOR: i64 = 31;
    51→var TOK_MATCH: i64 = 32;
    52→var TOK_ARROW: i64 = 33;
    53→
    54→// Token structure
    55→struct Token {
    56→    type: i64,
    57→    value: i64,
    58→    name: string,
    59→}
    60→
    61→// Lexer state
    62→struct Lexer {
    63→    input: string,
    64→    pos: i64,
    65→    tokens_count: i64,
    66→}
    67→
    68→// Helper: Check if character is digit
    69→fn is_digit(c: i64) -> i64 {
    70→    if (c >= 48 && c <= 57) {
    71→        return 1;  // '0' to '9'
    72→    }
    73→    return 0;
    74→}
    75→
    76→// Helper: Check if character is alphabetic
    77→fn is_alpha(c: i64) -> i64 {
    78→    if ((c >= 65 && c <= 90) || (c >= 97 && c <= 122)) {
    79→        return 1;  // 'A-Z' or 'a-z'
    80→    }
    81→    return 0;
    82→}
    83→
    84→// Helper: Check if character is alphanumeric
    85→fn is_alnum(c: i64) -> i64 {
    86→    if (is_alpha(c) == 1 || is_digit(c) == 1) {
    87→        return 1;
    88→    }
    89→    return 0;
    90→}
    91→
    92→// Helper: Check if character is whitespace
    93→fn is_space(c: i64) -> i64 {
    94→    if (c == 32 || c == 9 || c == 10 || c == 13) {
    95→        return 1;  // space, tab, newline, carriage return
    96→    }
    97→    return 0;
    98→}
    99→
   100→// Helper: Get string length
   101→fn str_len(s: string) -> i64 {
   102→    var i: i64 = 0;
   103→    while (i < 10000) {
   104→        var c: i64 = 0;  // null terminator
   105→        if (c == 0) {
   106→            return i;
   107→        }
   108→        i = i + 1;
   109→    }
   110→    return 10000;
   111→}
   112→
   113→// Helper: Compare strings
   114→fn str_cmp(s1: string, s2: string) -> i64 {
   115→    var i: i64 = 0;
   116→    while (i < 1000) {
   117→        var c1: i64 = 0;  // simplified
   118→        var c2: i64 = 0;  // simplified
   119→        if (c1 != c2) {
   120→            return 0;
   121→        }
   122→        if (c1 == 0) {
   123→            return 1;
   124→        }
   125→        i = i + 1;
   126→    }
   127→    return 1;
   128→}
   129→
   130→// Helper: Check if identifier is keyword
   131→fn is_keyword(name: string) -> i64 {
   132→    if (str_cmp(name, "fn") == 1) return TOK_FN;
   133→    if (str_cmp(name, "let") == 1) return TOK_LET;
   134→    if (str_cmp(name, "var") == 1) return TOK_VAR;
   135→    if (str_cmp(name, "return") == 1) return TOK_RETURN;
   136→    if (str_cmp(name, "if") == 1) return TOK_IF;
   137→    if (str_cmp(name, "else") == 1) return TOK_ELSE;
   138→    if (str_cmp(name, "while") == 1) return TOK_WHILE;
   139→    if (str_cmp(name, "for") == 1) return TOK_FOR;
   140→    if (str_cmp(name, "match") == 1) return TOK_MATCH;
   141→    return 0;  // Not a keyword, it's an identifier
   142→}
   143→
   144→// Main tokenizer function
   145→fn tokenize(input: string) -> [Token] {
   146→    var tokens: [Token];
   147→    var i: i64 = 0;
   148→    var count: i64 = 0;
   149→
   150→    while (i < 10000) {
   151→        // Get current character
   152→        var c: i64 = 0;  // Would be input[i] in real impl
   153→
   154→        // End of input
   155→        if (c == 0) {
   156→            break;
   157→        }
   158→
   159→        // Skip whitespace
   160→        if (is_space(c) == 1) {
   161→            i = i + 1;
   162→            continue;
   163→        }
   164→
   165→        // Number: 123
   166→        if (is_digit(c) == 1) {
   167→            var num: i64 = 0;
   168→            while (i < 10000 && is_digit(c) == 1) {
   169→                num = num * 10 + (c - 48);
   170→                i = i + 1;
   171→                c = 0;  // Would be input[i]
   172→            }
   173→            // Add token
   174→            tokens[count].type = TOK_INT;
   175→            tokens[count].value = num;
   176→            count = count + 1;
   177→            continue;
   178→        }
   179→
   180→        // Identifier or keyword
   181→        if (is_alpha(c) == 1 || c == 95) {  // '_' = 95
   182→            var name: string = "";
   183→            var name_len: i64 = 0;
   184→            while (i < 10000 && (is_alnum(c) == 1 || c == 95)) {
   185→                // Append c to name (simplified)
   186→                name_len = name_len + 1;
   187→                i = i + 1;
   188→                c = 0;  // Would be input[i]
   189→            }
   190→            // Check if keyword
   191→            var kw: i64 = is_keyword(name);
   192→            if (kw != 0) {
   193→                tokens[count].type = kw;
   194→            } else {
   195→                tokens[count].type = TOK_IDENT;
   196→                tokens[count].name = name;
   197→            }
   198→            count = count + 1;
   199→            continue;
   200→        }
   201→
   202→        // Operators and punctuation
   203→        if (c == 43) {  // '+'
   204→            tokens[count].type = TOK_PLUS;
   205→            i = i + 1;
   206→            count = count + 1;
   207→            continue;
   208→        }
   209→
   210→        if (c == 45) {  // '-'
   211→            var next: i64 = 0;  // input[i+1]
   212→            if (next == 62) {  // '-' followed by '>' = '->'
   213→                tokens[count].type = TOK_ARROW;
   214→                i = i + 2;
   215→            } else {
   216→                tokens[count].type = TOK_MINUS;
   217→                i = i + 1;
   218→            }
   219→            count = count + 1;
   220→            continue;
   221→        }
   222→
   223→        if (c == 42) {  // '*'
   224→            tokens[count].type = TOK_STAR;
   225→            i = i + 1;
   226→            count = count + 1;
   227→            continue;
   228→        }
   229→
   230→        if (c == 47) {  // '/'
   231→            tokens[count].type = TOK_SLASH;
   232→            i = i + 1;
   233→            count = count + 1;
   234→            continue;
   235→        }
   236→
   237→        if (c == 61) {  // '='
   238→            var next: i64 = 0;  // input[i+1]
   239→            if (next == 61) {  // '=='
   240→                tokens[count].type = TOK_EQ;
   241→                i = i + 2;
   242→            } else {
   243→                tokens[count].type = TOK_ASSIGN;
   244→                i = i + 1;
   245→            }
   246→            count = count + 1;
   247→            continue;
   248→        }
   249→
   250→        if (c == 33) {  // '!'
   251→            var next: i64 = 0;  // input[i+1]
   252→            if (next == 61) {  // '!='
   253→                tokens[count].type = TOK_NE;
   254→                i = i + 2;
   255→            } else {
   256→                tokens[count].type = TOK_NOT;
   257→                i = i + 1;
   258→            }
   259→            count = count + 1;
   260→            continue;
   261→        }
   262→
   263→        if (c == 60) {  // '<'
   264→            var next: i64 = 0;  // input[i+1]
   265→            if (next == 61) {  // '<='
   266→                tokens[count].type = TOK_LE;
   267→                i = i + 2;
   268→            } else {
   269→                tokens[count].type = TOK_LT;
   270→                i = i + 1;
   271→            }
   272→            count = count + 1;
   273→            continue;
   274→        }
   275→
   276→        if (c == 62) {  // '>'
   277→            var next: i64 = 0;  // input[i+1]
   278→            if (next == 61) {  // '>='
   279→                tokens[count].type = TOK_GE;
   280→                i = i + 2;
   281→            } else {
   282→                tokens[count].type = TOK_GT;
   283→                i = i + 1;
   284→            }
   285→            count = count + 1;
   286→            continue;
   287→        }
   288→
   289→        if (c == 38 && next == 38) {  // '&&'
   290→            tokens[count].type = TOK_AND;
   291→            i = i + 2;
   292→            count = count + 1;
   293→            continue;
   294→        }
   295→
   296→        if (c == 124 && next == 124) {  // '||'
   297→            tokens[count].type = TOK_OR;
   298→            i = i + 2;
   299→            count = count + 1;
   300→            continue;
   301→        }
   302→
   303→        // Single character tokens
   304→        if (c == 40) {  // '('
   305→            tokens[count].type = TOK_LPAREN;
   306→            i = i + 1;
   307→            count = count + 1;
   308→            continue;
   309→        }
   310→
   311→        if (c == 41) {  // ')'
   312→            tokens[count].type = TOK_RPAREN;
   313→            i = i + 1;
   314→            count = count + 1;
   315→            continue;
   316→        }
   317→
   318→        if (c == 123) {  // '{'
   319→            tokens[count].type = TOK_LBRACE;
   320→            i = i + 1;
   321→            count = count + 1;
   322→            continue;
   323→        }
   324→
   325→        if (c == 125) {  // '}'
   326→            tokens[count].type = TOK_RBRACE;
   327→            i = i + 1;
   328→            count = count + 1;
   329→            continue;
   330→        }
   331→
   332→        if (c == 59) {  // ';'
   333→            tokens[count].type = TOK_SEMICOLON;
   334→            i = i + 1;
   335→            count = count + 1;
   336→            continue;
   337→        }
   338→
   339→        if (c == 44) {  // ','
   340→            tokens[count].type = TOK_COMMA;
   341→            i = i + 1;
   342→            count = count + 1;
   343→            continue;
   344→        }
   345→
   346→        if (c == 58) {  // ':'
   347→            tokens[count].type = TOK_COLON;
   348→            i = i + 1;
   349→            count = count + 1;
   350→            continue;
   351→        }
   352→
   353→        // Unknown character, skip
   354→        i = i + 1;
   355→    }
   356→
   357→    // Add EOF token
   358→    tokens[count].type = TOK_EOF;
   359→    count = count + 1;
   360→
   361→    return tokens;
   362→}
   363→
   364→// ============================================================
   365→// Part 2: PARSER (AST Construction)
   366→// ============================================================
   367→
   368→// AST Node types
   369→var AST_PROGRAM: i64 = 1;
   370→var AST_FUNC: i64 = 2;
   371→var AST_VAR: i64 = 3;
   372→var AST_BINOP: i64 = 4;
   373→var AST_LITERAL: i64 = 5;
   374→var AST_IDENT: i64 = 6;
   375→var AST_CALL: i64 = 7;
   376→var AST_IF: i64 = 8;
   377→var AST_WHILE: i64 = 9;
   378→var AST_RETURN: i64 = 10;
   379→var AST_BLOCK: i64 = 11;
   380→
   381→struct ASTNode {
   382→    type: i64,
   383→    name: string,
   384→    value: i64,
   385→    op: i64,
   386→}
   387→
   388→struct Parser {
   389→    tokens: [Token],
   390→    pos: i64,
   391→}
   392→
   393→// ============================================================
   394→// Parser Helper Functions
   395→// ============================================================
   396→
   397→// Get current token
   398→fn current_token(parser: Parser) -> Token {
   399→    var token: Token;
   400→    // Simplified: would be parser.tokens[parser.pos]
   401→    return token;
   402→}
   403→
   404→// Peek at next token without advancing
   405→fn peek_token(parser: Parser) -> Token {
   406→    var token: Token;
   407→    // Simplified: would be parser.tokens[parser.pos + 1]
   408→    return token;
   409→}
   410→
   411→// Advance to next token
   412→fn advance(parser: Parser) -> i64 {
   413→    parser.pos = parser.pos + 1;
   414→    return parser.pos;
   415→}
   416→
   417→// Check if current token is of type
   418→fn match_token(parser: Parser, type_: i64) -> i64 {
   419→    var token: Token;
   420→    token = current_token(parser);
   421→    if (token.type == type_) {
   422→        return 1;
   423→    }
   424→    return 0;
   425→}
   426→
   427→// Consume token of expected type
   428→fn consume(parser: Parser, type_: i64) -> i64 {
   429→    if (match_token(parser, type_) == 1) {
   430→        advance(parser);
   431→        return 1;
   432→    }
   433→    return 0;  // Error: unexpected token
   434→}
   435→
   436→// ============================================================
   437→// Parser Functions
   438→// ============================================================
   439→
   440→// Parse a program: [function_list]
   441→// program = function*
   442→fn parse_program(tokens: [Token]) -> ASTNode {
   443→    var ast: ASTNode;
   444→    var parser: Parser;
   445→    var count: i64 = 0;
   446→    var func: ASTNode;
   447→
   448→    parser.tokens = tokens;
   449→    parser.pos = 0;
   450→
   451→    ast.type = AST_PROGRAM;
   452→
   453→    // Parse function declarations
   454→    while (match_token(parser, TOK_FN) == 1) {
   455→        func = parse_function(parser);
   456→        // Would store in ast.children[count]
   457→        count = count + 1;
   458→    }
   459→
   460→    // Expect EOF
   461→    if (match_token(parser, TOK_EOF) == 0) {
   462→        return ast;  // Error: expected EOF
   463→    }
   464→
   465→    return ast;
   466→}
   467→
   468→// Parse a function definition
   469→// function = 'fn' identifier '(' parameters ')' '->' type '{' statement* '}'
   470→fn parse_function(parser: Parser) -> ASTNode {
   471→    var ast: ASTNode;
   472→    var param_count: i64 = 0;
   473→    var stmt: ASTNode;
   474→
   475→    ast.type = AST_FUNC;
   476→
   477→    // Expect 'fn'
   478→    if (consume(parser, TOK_FN) == 0) {
   479→        return ast;  // Error
   480→    }
   481→
   482→    // Parse function name
   483→    if (match_token(parser, TOK_IDENT) == 0) {
   484→        return ast;  // Error: expected identifier
   485→    }
   486→    // ast.name = current_token(parser).name
   487→    advance(parser);
   488→
   489→    // Parse parameters: '(' param_list ')'
   490→    if (consume(parser, TOK_LPAREN) == 0) {
   491→        return ast;  // Error
   492→    }
   493→
   494→    // Parse parameter list
   495→    while (match_token(parser, TOK_RPAREN) == 0) {
   496→        // param = identifier ':' type
   497→        if (match_token(parser, TOK_IDENT) == 0) {
   498→            break;  // Error
   499→        }
   500→        advance(parser);
   501→
   502→        if (consume(parser, TOK_COLON) == 0) {
   503→            break;  // Error
   504→        }
   505→
   506→        // Parse type
   507→        if (match_token(parser, TOK_IDENT) == 0) {
   508→            break;  // Error
   509→        }
   510→        advance(parser);
   511→
   512→        param_count = param_count + 1;
   513→
   514→        // Check for comma
   515→        if (match_token(parser, TOK_COMMA) == 1) {
   516→            advance(parser);
   517→        }
   518→    }
   519→
   520→    // Consume ')'
   521→    consume(parser, TOK_RPAREN);
   522→
   523→    // Parse return type: '->' type
   524→    if (consume(parser, TOK_ARROW) == 0) {
   525→        return ast;  // Error
   526→    }
   527→
   528→    if (match_token(parser, TOK_IDENT) == 0) {
   529→        return ast;  // Error: expected type
   530→    }
   531→    advance(parser);
   532→
   533→    // Parse function body: '{' statement* '}'
   534→    if (consume(parser, TOK_LBRACE) == 0) {
   535→        return ast;  // Error
   536→    }
   537→
   538→    // Parse statements until '}'
   539→    var stmt_count: i64 = 0;
   540→    while (match_token(parser, TOK_RBRACE) == 0 && match_token(parser, TOK_EOF) == 0) {
   541→        stmt = parse_statement(parser);
   542→        // Would store in ast.body[stmt_count]
   543→        stmt_count = stmt_count + 1;
   544→    }
   545→
   546→    // Consume '}'
   547→    consume(parser, TOK_RBRACE);
   548→
   549→    return ast;
   550→}
   551→
   552→// Parse a statement
   553→// statement = var_decl | assignment | return_stmt | if_stmt | while_stmt | block
   554→fn parse_statement(parser: Parser) -> ASTNode {
   555→    var ast: ASTNode;
   556→    var expr: ASTNode;
   557→
   558→    ast.type = AST_BLOCK;
   559→
   560→    // 'var' declaration: var name: type = expr;
   561→    if (match_token(parser, TOK_VAR) == 1) {
   562→        advance(parser);
   563→
   564→        // Parse name
   565→        if (match_token(parser, TOK_IDENT) == 0) {
   566→            return ast;  // Error
   567→        }
   568→        advance(parser);
   569→
   570→        // Parse type
   571→        if (consume(parser, TOK_COLON) == 0) {
   572→            return ast;  // Error
   573→        }
   574→        if (match_token(parser, TOK_IDENT) == 0) {
   575→            return ast;  // Error: expected type
   576→        }
   577→        advance(parser);
   578→
   579→        // Parse optional initialization
   580→        if (match_token(parser, TOK_ASSIGN) == 1) {
   581→            advance(parser);
   582→            expr = parse_expression(parser);
   583→        }
   584→
   585→        // Consume ';'
   586→        consume(parser, TOK_SEMICOLON);
   587→        return ast;
   588→    }
   589→
   590→    // 'let' declaration: let name = expr;
   591→    if (match_token(parser, TOK_LET) == 1) {
   592→        advance(parser);
   593→
   594→        if (match_token(parser, TOK_IDENT) == 0) {
   595→            return ast;  // Error
   596→        }
   597→        advance(parser);
   598→
   599→        if (consume(parser, TOK_ASSIGN) == 0) {
   600→            return ast;  // Error
   601→        }
   602→
   603→        expr = parse_expression(parser);
   604→        consume(parser, TOK_SEMICOLON);
   605→        return ast;
   606→    }
   607→
   608→    // 'return' statement
   609→    if (match_token(parser, TOK_RETURN) == 1) {
   610→        advance(parser);
   611→        ast.type = AST_RETURN;
   612→
   613→        if (match_token(parser, TOK_SEMICOLON) == 0) {
   614→            expr = parse_expression(parser);
   615→        }
   616→
   617→        consume(parser, TOK_SEMICOLON);
   618→        return ast;
   619→    }
   620→
   621→    // 'if' statement
   622→    if (match_token(parser, TOK_IF) == 1) {
   623→        advance(parser);
   624→        ast.type = AST_IF;
   625→
   626→        // Parse condition
   627→        if (consume(parser, TOK_LPAREN) == 0) {
   628→            return ast;  // Error
   629→        }
   630→        expr = parse_expression(parser);
   631→        if (consume(parser, TOK_RPAREN) == 0) {
   632→            return ast;  // Error
   633→        }
   634→
   635→        // Parse then block
   636→        if (consume(parser, TOK_LBRACE) == 0) {
   637→            return ast;  // Error
   638→        }
   639→        while (match_token(parser, TOK_RBRACE) == 0) {
   640→            parse_statement(parser);
   641→        }
   642→        consume(parser, TOK_RBRACE);
   643→
   644→        // Parse else block (optional)
   645→        if (match_token(parser, TOK_ELSE) == 1) {
   646→            advance(parser);
   647→            if (consume(parser, TOK_LBRACE) == 0) {
   648→                return ast;  // Error
   649→            }
   650→            while (match_token(parser, TOK_RBRACE) == 0) {
   651→                parse_statement(parser);
   652→            }
   653→            consume(parser, TOK_RBRACE);
   654→        }
   655→
   656→        return ast;
   657→    }
   658→
   659→    // 'while' statement
   660→    if (match_token(parser, TOK_WHILE) == 1) {
   661→        advance(parser);
   662→        ast.type = AST_WHILE;
   663→
   664→        if (consume(parser, TOK_LPAREN) == 0) {
   665→            return ast;  // Error
   666→        }
   667→        expr = parse_expression(parser);
   668→        if (consume(parser, TOK_RPAREN) == 0) {
   669→            return ast;  // Error
   670→        }
   671→
   672→        if (consume(parser, TOK_LBRACE) == 0) {
   673→            return ast;  // Error
   674→        }
   675→        while (match_token(parser, TOK_RBRACE) == 0) {
   676→            parse_statement(parser);
   677→        }
   678→        consume(parser, TOK_RBRACE);
   679→
   680→        return ast;
   681→    }
   682→
   683→    // Expression statement: expr;
   684→    expr = parse_expression(parser);
   685→    consume(parser, TOK_SEMICOLON);
   686→
   687→    return ast;
   688→}
   689→
   690→// Parse an expression
   691→// expression = term (('+' | '-') term)*
   692→fn parse_expression(parser: Parser) -> ASTNode {
   693→    var ast: ASTNode;
   694→    var left: ASTNode;
   695→    var right: ASTNode;
   696→    var op: i64;
   697→
   698→    ast.type = AST_BINOP;
   699→
