   706→            op = TOK_PLUS;
   707→        } else {
   708→            op = TOK_MINUS;
   709→        }
   710→        advance(parser);
   711→
   712→        right = parse_term(parser);
   713→
   714→        // Build binary operation node
   715→        ast.op = op;
   716→        // ast.left = left
   717→        // ast.right = right
   718→        left = ast;
   719→    }
   720→
   721→    return left;
   722→}
   723→
   724→// Parse a term: factor (('*' | '/') factor)*
