   798→        advance(parser);
   799→        expr = parse_expression(parser);
   800→        consume(parser, TOK_RPAREN);
   801→        return expr;
   802→    }
   803→
   804→    // Error: unexpected token
   805→    ast.type = 0;  // Invalid
   806→    return ast;
   807→}
   808→
   809→// ============================================================
   810→// Part 3: CODEGEN (C Code Generation)
   811→// ============================================================
   812→
   813→// Generate C code for an AST
   814→fn codegen(ast: ASTNode) -> string {
   815→    var output: string = "";
   816→
   817→    // Headers
   818→    output = output + "#include <stdio.h>\n";
