   275→        tconsume(p,TOK_ASSIGN);
   276→        n->right=parse_expr(p);
   277→        tconsume(p,TOK_SEMICOLON);
   278→        return n;
   279→    }
   280→    if (tmatch(p,TOK_RETURN)) {
   281→        tadv(p);
   282→        ASTNode *n=new_node(AST_RETURN);
   283→        if (!tmatch(p,TOK_SEMICOLON)) n->right=parse_expr(p);
   284→        tconsume(p,TOK_SEMICOLON);
   285→        return n;
   286→    }
   287→    if (tmatch(p,TOK_IF)) {
   288→        tadv(p);
   289→        ASTNode *n=new_node(AST_IF);
   290→        tconsume(p,TOK_LPAREN); n->left=parse_expr(p); tconsume(p,TOK_RPAREN);
   291→        tconsume(p,TOK_LBRACE);
   292→        while(!tmatch(p,TOK_RBRACE)&&!tmatch(p,TOK_EOF))
   293→            n->children[n->children_count++]=parse_stmt(p);
   294→        tconsume(p,TOK_RBRACE);
   295→        n->then_count=n->children_count;
   296→        if (tconsume(p,TOK_ELSE)) {
   297→            tconsume(p,TOK_LBRACE);
   298→            while(!tmatch(p,TOK_RBRACE)&&!tmatch(p,TOK_EOF))
   299→                n->children[n->children_count++]=parse_stmt(p);
   300→            tconsume(p,TOK_RBRACE);
   301→        }
   302→        return n;
   303→    }
   304→    if (tmatch(p,TOK_WHILE)) {
   305→        tadv(p);
   306→        ASTNode *n=new_node(AST_WHILE);
   307→        tconsume(p,TOK_LPAREN); n->left=parse_expr(p); tconsume(p,TOK_RPAREN);
   308→        tconsume(p,TOK_LBRACE);
   309→        while(!tmatch(p,TOK_RBRACE)&&!tmatch(p,TOK_EOF))
   310→            n->children[n->children_count++]=parse_stmt(p);
   311→        tconsume(p,TOK_RBRACE);
   312→        return n;
   313→    }
   314→    // Assignment: ident = expr;
   315→    if (tmatch(p,TOK_IDENT) && p->pos+1<p->count && p->tokens[p->pos+1].type==TOK_ASSIGN) {
   316→        ASTNode *n=new_node(AST_ASSIGN);
   317→        strcpy(n->name,tcur(p)->name); tadv(p); tadv(p);
   318→        n->right=parse_expr(p);
   319→        tconsume(p,TOK_SEMICOLON);
   320→        return n;
   321→    }
   322→    // Expression statement
   323→    ASTNode *n=new_node(AST_EXPR_STMT);
   324→    n->right=parse_expr(p);
   325→    tconsume(p,TOK_SEMICOLON);
   326→    return n;
   327→}
