   329→static ASTNode* parse_expr(Parser *p) {
   330→    ASTNode *left=parse_and_expr(p);
   331→    while (tmatch(p,TOK_OR)) {
   332→        ASTNode *n=new_node(AST_BINOP); n->op=TOK_OR; tadv(p);
   333→        n->left=left; n->right=parse_and_expr(p); left=n;
   334→    }
   335→    return left;
   336→}
   337→static ASTNode* parse_and_expr(Parser *p) {
   338→    ASTNode *left=parse_cmp(p);
   339→    while (tmatch(p,TOK_AND)) {
   340→        ASTNode *n=new_node(AST_BINOP); n->op=TOK_AND; tadv(p);
   341→        n->left=left; n->right=parse_cmp(p); left=n;
   342→    }
   343→    return left;
   344→}
   345→static ASTNode* parse_cmp(Parser *p) {
   346→    ASTNode *left=parse_add(p);
   347→    if (tmatch(p,TOK_EQ)||tmatch(p,TOK_NE)||tmatch(p,TOK_LT)||
   348→        tmatch(p,TOK_GT)||tmatch(p,TOK_LE)||tmatch(p,TOK_GE)) {
   349→        ASTNode *n=new_node(AST_BINOP); n->op=tcur(p)->type; tadv(p);
   350→        n->left=left; n->right=parse_add(p); return n;
   351→    }
   352→    return left;
   353→}
   354→static ASTNode* parse_add(Parser *p) {
   355→    ASTNode *left=parse_mul(p);
   356→    while (tmatch(p,TOK_PLUS)||tmatch(p,TOK_MINUS)) {
   357→        ASTNode *n=new_node(AST_BINOP); n->op=tcur(p)->type; tadv(p);
   358→        n->left=left; n->right=parse_mul(p); left=n;
   359→    }
   360→    return left;
   361→}
   362→static ASTNode* parse_mul(Parser *p) {
   363→    ASTNode *left=parse_primary(p);
   364→    while (tmatch(p,TOK_STAR)||tmatch(p,TOK_SLASH)) {
   365→        ASTNode *n=new_node(AST_BINOP); n->op=tcur(p)->type; tadv(p);
   366→        n->left=left; n->right=parse_primary(p); left=n;
   367→    }
   368→    return left;
   369→}
   370→static ASTNode* parse_primary(Parser *p) {
   371→    if (tmatch(p,TOK_INT)) {
   372→        ASTNode *n=new_node(AST_LITERAL); n->value=tcur(p)->value; tadv(p); return n;
   373→    }
   374→    if (tmatch(p,TOK_STRING)) {
   375→        ASTNode *n=new_node(AST_STRING); strcpy(n->str_val,tcur(p)->str_val); tadv(p); return n;
   376→    }
   377→    if (tmatch(p,TOK_IDENT)) {
   378→        ASTNode *n=new_node(AST_IDENT); strcpy(n->name,tcur(p)->name); tadv(p);
   379→        if (tconsume(p,TOK_LPAREN)) {
   380→            n->type=AST_CALL;
   381→            while(!tmatch(p,TOK_RPAREN)&&!tmatch(p,TOK_EOF)) {
   382→                n->children[n->children_count++]=parse_expr(p);
   383→                tconsume(p,TOK_COMMA);
   384→            }
   385→            tconsume(p,TOK_RPAREN);
   386→        }
   387→        return n;
   388→    }
   389→    if (tconsume(p,TOK_LPAREN)) {
   390→        ASTNode *e=parse_expr(p); tconsume(p,TOK_RPAREN); return e;
   391→    }
   392→    if (tmatch(p,TOK_NOT)) {
   393→        tadv(p); ASTNode *n=new_node(AST_BINOP); n->op=TOK_NOT;
   394→        n->right=parse_primary(p); return n;
   395→    }
   396→    if (tmatch(p,TOK_MINUS)) {
   397→        tadv(p); ASTNode *n=new_node(AST_BINOP); n->op=TOK_MINUS;
   398→        ASTNode *z=new_node(AST_LITERAL); z->value=0;
   399→        n->left=z; n->right=parse_primary(p); return n;
   400→    }
   401→    return new_node(0);
   402→}
