   404→// ============================================================
   405→// Part 3: CODEGEN
   406→// ============================================================
   407→
   408→#define OUTPUT_SIZE  1000000
   409→static char out_buf[OUTPUT_SIZE];
   410→static int  out_pos = 0;
   411→
   412→static void gout(const char *s) {
   413→    if (!s) return;
   414→    int len=(int)strlen(s);
   415→    if (out_pos+len < OUTPUT_SIZE-1) {
   416→        memcpy(out_buf+out_pos, s, len);
   417→        out_pos += len;
   418→        out_buf[out_pos] = '\0';
   419→    }
   420→}
