   422→static const char* fl2c(const char *fl) {
   423→    if (!fl||!fl[0]) return "long";
   424→    if (strcmp(fl,"i64")==0||strcmp(fl,"auto")==0) return "long";
   425→    if (strcmp(fl,"i32")==0) return "int";
   426→    if (strcmp(fl,"f64")==0) return "double";
   427→    if (strcmp(fl,"bool")==0) return "int";
   428→    if (strcmp(fl,"string")==0) return "const char*";
   429→    return "long";
   430→}
   431→
   432→// Expression codegen using a simple pool
   433→#define EP_SIZE  64
   434→#define EP_BUFSZ 4096
   435→static char  ep[EP_SIZE][EP_BUFSZ];
   436→static int   ep_depth = 0;
   437→
   438→static char* gen_expr(ASTNode *ast);
   439→
   440→static char* ep_alloc(void) {
   441→    char *b = ep[ep_depth % EP_SIZE];
   442→    ep_depth++;
   443→    b[0]='\0';
   444→    return b;
   445→}
   446→static void ep_free(void) { if(ep_depth>0) ep_depth--; }
   447→
   448→static const char* binop_str(int op) {
   449→    switch(op){
   450→        case TOK_PLUS:  return "+";
   451→        case TOK_MINUS: return "-";
   452→        case TOK_STAR:  return "*";
   453→        case TOK_SLASH: return "/";
   454→        case TOK_EQ:    return "==";
   455→        case TOK_NE:    return "!=";
   456→        case TOK_LT:    return "<";
   457→        case TOK_GT:    return ">";
   458→        case TOK_LE:    return "<=";
   459→        case TOK_GE:    return ">=";
   460→        case TOK_AND:   return "&&";
   461→        case TOK_OR:    return "||";
   462→    }
   463→    return "?";
   464→}
   465→
   466→static char* gen_expr(ASTNode *ast) {
   467→    char *buf = ep_alloc();
   468→    if (!ast || ast->type==0) { strcpy(buf,"0"); return buf; }
   469→    switch(ast->type) {
   470→        case AST_LITERAL:
   471→            snprintf(buf, EP_BUFSZ, "%d", ast->value);
   472→            break;
   473→        case AST_STRING:
   474→            snprintf(buf, EP_BUFSZ, "\"%s\"", ast->str_val);
   475→            break;
   476→        case AST_IDENT:
   477→            snprintf(buf, EP_BUFSZ, "%s", ast->name);
   478→            break;
   479→        case AST_CALL: {
   480→            char args[EP_BUFSZ]="";
   481→            for (int i=0; i<ast->children_count; i++) {
   482→                if (i>0) strncat(args,", ",EP_BUFSZ-strlen(args)-1);
   483→                char *a=gen_expr(ast->children[i]);
   484→                strncat(args,a,EP_BUFSZ-strlen(args)-1);
   485→                ep_free();
   486→            }
   487→            snprintf(buf, EP_BUFSZ, "%s(%s)", ast->name, args);
   488→            break;
   489→        }
   490→        case AST_BINOP: {
   491→            if (ast->op==TOK_NOT) {
   492→                char *r=gen_expr(ast->right);
   493→                snprintf(buf,EP_BUFSZ,"(!%s)",r);
   494→                ep_free();
   495→            } else {
   496→                char *l=gen_expr(ast->left);
   497→                char lc[EP_BUFSZ]; strncpy(lc,l,EP_BUFSZ-1); ep_free();
   498→                char *r=gen_expr(ast->right);
   499→                snprintf(buf,EP_BUFSZ,"(%s %s %s)",lc,binop_str(ast->op),r);
   500→                ep_free();
   501→            }
   502→            break;
   503→        }
   504→        default: strcpy(buf,"0"); break;
   505→    }
   506→    return buf;
   507→}
   508→
   509→static void gen_stmts(ASTNode **stmts, int count, int indent);
   510→
   511→static void ind(int level) { for(int i=0;i<level;i++) gout("    "); }
   512→
   513→static void gen_stmt(ASTNode *ast, int indent) {
   514→    if (!ast) return;
   515→    switch(ast->type) {
   516→        case AST_VAR: {
   517→            const char *ct=fl2c(ast->type_name);
   518→            ind(indent); gout(ct); gout(" "); gout(ast->name);
   519→            if (ast->right) {
   520→                gout(" = "); char *e=gen_expr(ast->right); gout(e); ep_free();
   521→            }
   522→            gout(";\n");
   523→            break;
   524→        }
   525→        case AST_ASSIGN: {
   526→            ind(indent); gout(ast->name); gout(" = ");
   527→            char *e=gen_expr(ast->right); gout(e); ep_free();
   528→            gout(";\n");
   529→            break;
   530→        }
   531→        case AST_RETURN: {
   532→            ind(indent);
   533→            if (ast->right) {
   534→                gout("return "); char *e=gen_expr(ast->right); gout(e); ep_free();
   535→                gout(";\n");
   536→            } else {
   537→                gout("return;\n");
   538→            }
   539→            break;
   540→        }
   541→        case AST_IF: {
   542→            ind(indent); gout("if (");
   543→            char *c=gen_expr(ast->left); gout(c); ep_free();
   544→            gout(") {\n");
   545→            gen_stmts(ast->children, ast->then_count, indent+1);
   546→            if (ast->children_count > ast->then_count) {
   547→                ind(indent); gout("} else {\n");
   548→                gen_stmts(ast->children+ast->then_count,
   549→                          ast->children_count-ast->then_count, indent+1);
   550→            }
   551→            ind(indent); gout("}\n");
   552→            break;
   553→        }
   554→        case AST_WHILE: {
   555→            ind(indent); gout("while (");
   556→            char *c=gen_expr(ast->left); gout(c); ep_free();
   557→            gout(") {\n");
   558→            gen_stmts(ast->children, ast->children_count, indent+1);
   559→            ind(indent); gout("}\n");
   560→            break;
   561→        }
   562→        case AST_EXPR_STMT: {
   563→            if (ast->right) {
   564→                ind(indent); char *e=gen_expr(ast->right); gout(e); ep_free();
   565→                gout(";\n");
   566→            }
   567→            break;
   568→        }
   569→        default: break;
   570→    }
   571→}
   572→
   573→static void gen_stmts(ASTNode **stmts, int count, int indent) {
   574→    for (int i=0;i<count;i++) gen_stmt(stmts[i], indent);
   575→}
   576→
   577→static void gen_fwd(ASTNode *fn) {
   578→    int is_main = (strcmp(fn->name,"main")==0);
   579→    const char *rt = is_main ? "int" : fl2c(fn->type_name);
   580→    gout(rt); gout(" "); gout(fn->name); gout("(");
   581→    if (fn->params_count==0) {
   582→        gout("void");
   583→    } else {
   584→        for (int i=0;i<fn->params_count;i++) {
   585→            if (i>0) gout(", ");
   586→            gout(fl2c(fn->param_types[i])); gout(" "); gout(fn->param_names[i]);
   587→        }
   588→    }
   589→    gout(");\n");
   590→}
   591→
   592→static void gen_func(ASTNode *fn) {
   593→    int is_main = (strcmp(fn->name,"main")==0);
   594→    const char *rt = is_main ? "int" : fl2c(fn->type_name);
   595→    gout(rt); gout(" "); gout(fn->name); gout("(");
   596→    if (fn->params_count==0) {
   597→        gout("void");
   598→    } else {
   599→        for (int i=0;i<fn->params_count;i++) {
   600→            if (i>0) gout(", ");
   601→            gout(fl2c(fn->param_types[i])); gout(" "); gout(fn->param_names[i]);
   602→        }
   603→    }
   604→    gout(") {\n");
   605→    gen_stmts(fn->children, fn->children_count, 1);
   606→    gout("}\n\n");
   607→}
   608→
   609→static char* codegen(ASTNode *prog) {
   610→    out_pos=0; out_buf[0]='\0'; ep_depth=0;
   611→
   612→    gout("#include <stdio.h>\n");
   613→    gout("#include <stdlib.h>\n");
   614→    gout("#include <string.h>\n");
   615→    gout("#include <stdint.h>\n\n");
   616→
   617→    // Forward declarations
   618→    gout("/* Forward declarations */\n");
   619→    for (int i=0;i<prog->children_count;i++) {
   620→        ASTNode *fn=prog->children[i];
   621→        if (fn->type==AST_FUNC) gen_fwd(fn);
   622→    }
   623→    gout("\n");
   624→
   625→    // Non-main functions first, then main
   626→    for (int pass=0; pass<2; pass++) {
   627→        for (int i=0;i<prog->children_count;i++) {
   628→            ASTNode *fn=prog->children[i];
   629→            if (fn->type!=AST_FUNC) continue;
   630→            int is_main=(strcmp(fn->name,"main")==0);
   631→            if (pass==0 && is_main)  continue;
   632→            if (pass==1 && !is_main) continue;
   633→            gen_func(fn);
   634→        }
   635→    }
   636→
   637→    return out_buf;
   638→}
