   643→
   644→int main(int argc, char *argv[]) {
   645→    if (argc < 2) {
   646→        fprintf(stderr,"Usage: %s <input.fl> [output.c]\n",argv[0]);
   647→        return 1;
   648→    }
   649→    FILE *fp=fopen(argv[1],"r");
   650→    if (!fp) { fprintf(stderr,"Error: Cannot open '%s'\n",argv[1]); return 1; }
   651→    fseek(fp,0,SEEK_END); long fsz=ftell(fp); fseek(fp,0,SEEK_SET);
   652→    char *src=(char*)malloc(fsz+1);
   653→    fread(src,1,fsz,fp); src[fsz]='\0'; fclose(fp);
   654→
   655→    Lexer *lex = tokenize(src);
   656→    Parser parser; parser.tokens=lex->tokens; parser.pos=0; parser.count=lex->tokens_count;
   657→    ASTNode *prog = parse_program(&parser);
   658→    char *code = codegen(prog);
   659→
   660→    if (argc>=3) {
   661→        FILE *out=fopen(argv[2],"w");
   662→        if (!out){fprintf(stderr,"Error: Cannot write '%s'\n",argv[2]);return 1;}
   663→        fputs(code,out); fclose(out);
   664→        fprintf(stderr,"Generated: %s  (%d bytes)\n",argv[2],(int)strlen(code));
   665→    } else {
   666→        fputs(code,stdout);
   667→    }
   668→
   669→    free(src); free(lex->tokens); free(lex);
   670→    return 0;
   671→}
